#include <algorithm>

#include <pybind11/pybind11.h>
#include <torch/extension.h>

#include "acl/acl.h"
#include "torch_npu/csrc/core/npu/NPUStream.h"

#include "add_layer_norm_tiling.h"

extern "C" void add_layer_norm_do_fp32(
    uint32_t blockDim, void *stream,
    uint8_t *x, uint8_t *y, uint8_t *gamma, uint8_t *beta,
    uint8_t *out, uint8_t *mean, uint8_t *invRms, uint8_t *tiling);
extern "C" void add_layer_norm_do_fp16(
    uint32_t blockDim, void *stream,
    uint8_t *x, uint8_t *y, uint8_t *gamma, uint8_t *beta,
    uint8_t *out, uint8_t *mean, uint8_t *invRms, uint8_t *tiling);
extern "C" void add_layer_norm_do_bf16(
    uint32_t blockDim, void *stream,
    uint8_t *x, uint8_t *y, uint8_t *gamma, uint8_t *beta,
    uint8_t *out, uint8_t *mean, uint8_t *invRms, uint8_t *tiling);

namespace add_layer_norm_ext {

using LaunchFn = void (*)(uint32_t, void *,
    uint8_t *, uint8_t *, uint8_t *, uint8_t *,
    uint8_t *, uint8_t *, uint8_t *, uint8_t *);

pybind11::tuple run_add_layer_norm(
    const at::Tensor &x, const at::Tensor &y,
    const at::Tensor &gamma, const at::Tensor &beta,
    double eps = 1e-5)
{
    TORCH_CHECK(x.dim() == 2, "x must be [M, N]");
    TORCH_CHECK(y.dim() == 2, "y must be [M, N]");
    TORCH_CHECK(gamma.dim() == 1, "gamma must be [N]");
    TORCH_CHECK(beta.dim() == 1, "beta must be [N]");
    TORCH_CHECK(x.scalar_type() == at::kFloat ||
                x.scalar_type() == at::kHalf ||
                x.scalar_type() == at::kBFloat16, "x must be float32/float16/bfloat16");
    TORCH_CHECK(y.scalar_type() == x.scalar_type(), "dtype mismatch");
    TORCH_CHECK(gamma.scalar_type() == x.scalar_type(), "dtype mismatch");
    TORCH_CHECK(beta.scalar_type() == x.scalar_type(), "dtype mismatch");
    TORCH_CHECK(x.is_contiguous() && y.is_contiguous(), "must be contiguous");
    TORCH_CHECK(x.sizes() == y.sizes(), "x,y shape mismatch");
    TORCH_CHECK(x.sizes()[1] == gamma.sizes()[0], "gamma shape mismatch");
    TORCH_CHECK(x.sizes()[1] == beta.sizes()[0], "beta shape mismatch");

    const auto m = static_cast<int32_t>(x.sizes()[0]);
    const auto n = static_cast<int32_t>(x.sizes()[1]);

    const int32_t mNum = (m + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
    const int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, mNum);
    const int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    at::Tensor out = at::empty_like(x);
    at::Tensor mean = at::empty({m}, x.options().dtype(at::kFloat));
    at::Tensor invRms = at::empty({m}, x.options().dtype(at::kFloat));

    at::Tensor tilingCpu = at::empty(
        {static_cast<long>(sizeof(AddLayerNormTiling))},
        at::device(at::kCPU).dtype(at::kByte));
    auto *t = reinterpret_cast<AddLayerNormTiling *>(tilingCpu.data_ptr());
    t->M = m; t->N = n;
    t->blockM = DEFAULT_BLOCK_M;
    t->usedCoreNum = usedCoreNum;
    t->tasksPerCore = tasksPerCore;
    t->eps = static_cast<float>(eps);
    t->invN = 1.0f / static_cast<float>(n);
    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);

    auto aclStream = c10_npu::getCurrentNPUStream().stream(false);
    LaunchFn launch = nullptr;
    if (x.scalar_type() == at::kFloat) launch = add_layer_norm_do_fp32;
    else if (x.scalar_type() == at::kHalf) launch = add_layer_norm_do_fp16;
    else if (x.scalar_type() == at::kBFloat16) launch = add_layer_norm_do_bf16;
    else TORCH_CHECK(false, "unsupported dtype");

    launch(usedCoreNum, aclStream,
        static_cast<uint8_t *>(const_cast<void *>(x.storage().data())),
        static_cast<uint8_t *>(const_cast<void *>(y.storage().data())),
        static_cast<uint8_t *>(const_cast<void *>(gamma.storage().data())),
        static_cast<uint8_t *>(const_cast<void *>(beta.storage().data())),
        static_cast<uint8_t *>(const_cast<void *>(out.storage().data())),
        static_cast<uint8_t *>(const_cast<void *>(mean.storage().data())),
        static_cast<uint8_t *>(const_cast<void *>(invRms.storage().data())),
        static_cast<uint8_t *>(const_cast<void *>(tilingNpu.storage().data())));
    return pybind11::make_tuple(out, mean, invRms);
}

}  // namespace add_layer_norm_ext

PYBIND11_MODULE(_add_layer_norm_ext, m)
{
    m.doc() = "add_layer_norm extension";
    m.def("run_add_layer_norm", &add_layer_norm_ext::run_add_layer_norm, "");
}

