#include "add_layer_norm_kernel.h"

extern "C" __global__ __aicore__ void add_layer_norm_custom_fp16(
    GM_ADDR x, GM_ADDR y, GM_ADDR gamma, GM_ADDR beta,
    GM_ADDR out, GM_ADDR mean, GM_ADDR invRms, GM_ADDR tiling)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2);
    AscendC::TPipe pipe;
    AddLayerNormKernel<half> kernel;
    kernel.Init(x, y, gamma, beta, out, mean, invRms, tiling, &pipe);
    kernel.Process();
}

extern "C" void add_layer_norm_do_fp16(
    uint32_t blockDim, void *stream,
    uint8_t *x, uint8_t *y, uint8_t *gamma, uint8_t *beta,
    uint8_t *out, uint8_t *mean, uint8_t *invRms, uint8_t *tiling)
{
    add_layer_norm_custom_fp16<<<blockDim, nullptr, stream>>>(
        x, y, gamma, beta, out, mean, invRms, tiling);
}

